package com.example.crowdtransportfeedback.security;
import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.servlet.http.HttpServletResponse; import org.springframework.context.annotation.*; import org.springframework.http.MediaType; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import java.util.Map;
@Configuration @EnableMethodSecurity public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain chain(HttpSecurity h,JwtAuthenticationFilter jwt,ObjectMapper json)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/actuator/health").permitAll().anyRequest().authenticated()).exceptionHandling(e->e.authenticationEntryPoint((q,r,x)->write(json,r,401,"unauthenticated","Authentication required")).accessDeniedHandler((q,r,x)->write(json,r,403,"forbidden","Operation is not permitted"))).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}
 private static void write(ObjectMapper o,HttpServletResponse r,int status,String code,String message)throws java.io.IOException{r.setStatus(status);r.setContentType(MediaType.APPLICATION_JSON_VALUE);o.writeValue(r.getOutputStream(),Map.of("code",code,"message",message));}
}
